const PRESETS = {
 municipal:{name:'Municipal dream',terms:['architecture','city','building'],hue:185,warp:.25,blend:'screen',description:'Concrete, civic geometry, empty public space.'},
 velvet:{name:'Velvet decay',terms:['flower','textile','antique'],hue:315,warp:.55,blend:'lighten',description:'Soft ornament dissolving into damaged memory.'},
 broadcast:{name:'Feral broadcast',terms:['television','broadcast','radio'],hue:110,warp:.8,blend:'difference',description:'Transmission, signal ghosts, unstable channels.'},
 orbital:{name:'Orbital folklore',terms:['astronomy','moon','space'],hue:235,warp:.4,blend:'screen',description:'Celestial diagrams and machine-age myth.'},
 tidal:{name:'Tidal bureaucracy',terms:['ocean','map','coast'],hue:165,warp:.6,blend:'multiply',description:'Charts, coastlines, paperwork submerged.'},
 phantom:{name:'Phantom arcade',terms:['computer','game','software'],hue:20,warp:.7,blend:'exclusion',description:'Obsolete interfaces and electric afterimages.'}
};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});
function dateWindow(value,radius){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))throw Error('Choose a valid date.');
 const date=new Date(value+'T12:00:00Z');if(!Number.isFinite(+date)||date.toISOString().slice(0,10)!==value)throw Error('Choose a real calendar date.');
 if(date.getUTCFullYear()<1850||date>new Date())throw Error('Choose a date between 1850 and today.');
 const days=[0,30,365,1825].includes(Number(radius))?Number(radius):365;
 const iso=d=>d.toISOString().slice(0,10);
 return {selected:value,start:iso(new Date(+date-days*86400000)),end:iso(new Date(Math.min(Date.now(),+date+days*86400000))),days};
}
async function archivedFetch(url,limit=4*1024*1024){
 for(let i=0;i<5;i++){
  const u=new URL(url);if(u.protocol!=='https:'||!(u.hostname==='archive.org'||u.hostname.endsWith('.archive.org')))throw Error('Archive-only URLs are supported.');
  const response=await fetch(u,{redirect:'manual',signal:AbortSignal.timeout(18000),headers:{'User-Agent':'TemporalLoom/1.0 (archive visual instrument)'}});
  if([301,302,303,307,308].includes(response.status)){url=new URL(response.headers.get('location'),u).href.replace(/^http:/,'https:');continue;}
  if(!response.ok)throw Error('Archive service returned '+response.status+'. Try again or widen the date range.');
  if(Number(response.headers.get('content-length'))>limit)throw Error('Archive response is too large.');
  const reader=response.body.getReader(),parts=[];let size=0;
  while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();throw Error('Asset is too large for this session.');}parts.push(value);}
  const bytes=new Uint8Array(size);let offset=0;for(const p of parts){bytes.set(p,offset);offset+=p.length;}
  return {bytes,type:response.headers.get('content-type')||''};
 }
 throw Error('The archive redirected too many times.');
}
async function archiveJSON(url){const r=await archivedFetch(url);try{return JSON.parse(new TextDecoder().decode(r.bytes));}catch{throw Error('The archive returned an unexpected response. Try again shortly.');}}
async function searchSource(params){
 const preset=PRESETS[params.get('preset')]||PRESETS.municipal;
 const dates=dateWindow(params.get('date'),params.get('window'));
 if(params.get('source')==='wayback'){
  let site;try{site=new URL(params.get('site'));}catch{throw Error('Enter an https:// website or image URL for Wayback.');}
  if(!/^https?:$/.test(site.protocol)||site.username||site.password||site.hostname==='localhost'||!site.hostname.includes('.'))throw Error('Enter a public website URL.');
  const image=/\.(jpe?g|png|gif|webp)(?:$|\?)/i.test(site.href);
  const endpoint=new URL('https://web.archive.org/cdx/search/cdx');
  endpoint.searchParams.set('url',image?site.href:site.href.replace(/\/?$/,'/'));
  endpoint.searchParams.set('matchType',image?'exact':'prefix');
  endpoint.searchParams.set('output','json');endpoint.searchParams.set('fl','timestamp,original,mimetype,statuscode');
  endpoint.searchParams.append('filter','statuscode:200');endpoint.searchParams.append('filter','mimetype:image/(jpeg|png|gif|webp)');
  endpoint.searchParams.set('from',dates.start.replaceAll('-',''));endpoint.searchParams.set('to',dates.end.replaceAll('-',''));
  endpoint.searchParams.set('collapse','digest');endpoint.searchParams.set('limit','80');
  const rows=await archiveJSON(endpoint);if(!Array.isArray(rows))throw Error('Wayback returned no capture index.');
  const score=row=>Math.abs(Date.parse(row[0].slice(0,4)+'-'+row[0].slice(4,6)+'-'+row[0].slice(6,8))-Date.parse(dates.selected));
  const images=rows.slice(1).filter(row=>/^\d{14}$/.test(row[0])&&/^https?:/.test(row[1]||''));
  images.sort((a,b)=>{const relevance=r=>preset.terms.some(term=>r[1].toLowerCase().includes(term))?1:0;return relevance(b)-relevance(a)||score(a)-score(b);});
  return {dates,preset:preset.name,dateType:'Wayback capture date',note:'Preset words rank matching URL names; the selected website bounds this search. Capture dates are shown for every image.',assets:images.slice(0,16).map(row=>({title:new URL(row[1]).pathname.split('/').pop()||row[1],date:row[0].slice(0,4)+'-'+row[0].slice(4,6)+'-'+row[0].slice(6,8),source:'Wayback',original:row[1],link:'https://web.archive.org/web/'+row[0]+'/'+row[1],image:'/api/image?kind=wayback&timestamp='+row[0]+'&url='+encodeURIComponent(row[1])}))};
 }
 const genreTerms=typeof GENRES!=='undefined'?(GENRES[params.get('genre')]?.terms||[]):[];
 const terms=[...new Set([...preset.terms,...genreTerms])].map(t=>'"'+t+'"').join(' OR ');
 const q='(mediatype:image OR mediatype:texts) AND date:['+dates.start+'T00:00:00Z TO '+dates.end+'T23:59:59Z] AND ('+terms+')';
 const endpoint=new URL('https://archive.org/advancedsearch.php');endpoint.searchParams.set('q',q);endpoint.searchParams.set('output','json');endpoint.searchParams.set('rows','60');
 for(const field of ['identifier','title','date','mediatype'])endpoint.searchParams.append('fl[]',field);
 const result=await archiveJSON(endpoint);const docs=result.response?.docs;if(!Array.isArray(docs))throw Error('Archive search is temporarily unavailable.');
 docs.sort((a,b)=>Math.abs(Date.parse(a.date)-Date.parse(dates.selected))-Math.abs(Date.parse(b.date)-Date.parse(dates.selected)));
 return {dates,preset:preset.name,dateType:'Item publication / creation date',note:'Images and scanned-item covers, ranked by distance from your chosen date. Item dates describe the work, not when it was uploaded or captured.',assets:docs.filter(d=>/^[\w.-]+$/.test(d.identifier)).slice(0,16).map(d=>({title:d.title||d.identifier,date:String(d.date||'Unknown').slice(0,10),source:'Internet Archive',link:'https://archive.org/details/'+d.identifier,image:'/api/image?kind=ia&id='+encodeURIComponent(d.identifier)}))};
}
const GENRES = {
 ephemera:{name:'Print & ephemera',sites:['https://www.loc.gov/','https://www.si.edu/'],terms:['poster','advertising','magazine']},
 broadcast:{name:'Broadcast & music',sites:['https://www.bbc.co.uk/','https://www.mtv.com/'],terms:['television','music','broadcast']},
 science:{name:'Space & science',sites:['https://www.nasa.gov/','https://www.jpl.nasa.gov/'],terms:['space','science','astronomy']},
 digital:{name:'Early web & games',sites:['https://www.geocities.com/','https://www.wired.com/'],terms:['computer','game','internet']},
 nature:{name:'Nature & field studies',sites:['https://www.noaa.gov/','https://www.nps.gov/'],terms:['nature','wildlife','landscape']},
 architecture:{name:'Cities & architecture',sites:['https://www.loc.gov/','https://www.nyc.gov/'],terms:['architecture','city','building']}
};
async function search(params){
 const source=params.get('source')||'blended';
 if(source==='ia'||(source==='wayback'&&params.get('site'))||source==='wayback-site'){
  const direct=new URLSearchParams(params);if(source==='wayback-site')direct.set('source','wayback');return searchSource(direct);
 }
 const genre=GENRES[params.get('genre')]||GENRES.ephemera;
 const requests=[];
 if(source!=='wayback'){
  const p=new URLSearchParams(params);p.set('source','ia');requests.push({name:'Internet Archive',run:searchSource(p)});
 }
 for(const site of genre.sites){const p=new URLSearchParams(params);p.set('source','wayback');p.set('site',site);requests.push({name:new URL(site).hostname,run:searchSource(p)});}
 const results=await Promise.allSettled(requests.map(request=>request.run));
 const groups=[],notes=[];
 results.forEach((result,i)=>{if(result.status==='fulfilled'){groups.push(result.value.assets);notes.push(requests[i].name+': '+result.value.assets.length+' candidates');}else notes.push(requests[i].name+': unavailable');});
 const seen=new Set(),assets=[];for(let i=0;i<16;i++)for(const group of groups){const asset=group[i];if(asset&&!seen.has(asset.link)){seen.add(asset.link);assets.push(asset);}}
 if(results.every(result=>result.status==='rejected'))throw Error('Archive services are unavailable right now. Try again or use local images.');
 return {dates:dateWindow(params.get('date'),params.get('window')),preset:(PRESETS[params.get('preset')]||PRESETS.municipal).name,dateType:'Mixed sources · item dates and capture dates',note:'Genre: '+genre.name+'. Wayback samples a curated set of relevant websites, not the entire web. '+notes.join(' · ')+'. Each fragment retains its actual source date.',assets:assets.slice(0,36)};
}
